import "dotenv/config";
import { Client } from "pg";
import { requireLocalResetUrl, resetLocalData } from "./lib/reset-local-data";

async function main() {
  const args = process.argv.slice(2);
  if (
    args.length > 1 ||
    args.some((arg) => !["--apply", "--dry-run"].includes(arg))
  ) {
    throw new Error("Use --dry-run (default) or --apply.");
  }
  const client = new Client({
    connectionString: requireLocalResetUrl(process.env),
  });
  try {
    await client.connect();
    await client.query("SET search_path TO public");
    console.log(
      JSON.stringify(await resetLocalData(client, args.includes("--apply"))),
    );
    if (!args.includes("--apply"))
      console.log(
        "Dry run rolled back. Use npm run db:clear -- --apply to clear local test data.",
      );
  } finally {
    await client.end();
  }
}

void main().catch(() => {
  // Provider errors can include row contents or connection details.
  console.error(
    "Local data reset failed; no changes committed. Check the local database target, required global settings, and stop active app/worker processes.",
  );
  process.exitCode = 1;
});
